INSERT INTO complaint (complaint_id, part_id, delivery_id, complaint_date, defect_type, complaint_message) VALUES (3001, 1, 2002, '2026-04-22', 'SURFACE_DAMAGE', '실린더 라이너 표면에 긁힘이 확인되어 원인 확인과 조치 의견을 요청함.');
INSERT INTO complaint (complaint_id, part_id, delivery_id, complaint_date, defect_type, complaint_message) VALUES (3002, 2, 2007, '2026-05-20', 'PACKAGING_DAMAGE', '연료 분사 밸브의 외부 포장이 손상되어 포장 상태 개선을 요청함.');
INSERT INTO complaint (complaint_id, part_id, delivery_id, complaint_date, defect_type, complaint_message) VALUES (3003, 1, 2005, '2026-04-25', 'MISSING_LABEL', '실린더 라이너 포장에 부품 식별 라벨이 누락되어 식별 정보 확인을 요청함.');
INSERT INTO complaint (complaint_id, part_id, delivery_id, complaint_date, defect_type, complaint_message) VALUES (3004, 3, 2012, '2026-06-24', 'SURFACE_DAMAGE', '베어링 표면에 찍힘 흔적이 확인되어 납품 상태에 대한 확인을 요청함.');
INSERT INTO complaint (complaint_id, part_id, delivery_id, complaint_date, defect_type, complaint_message) VALUES (3005, 1, 2016, '2026-07-25', 'DIMENSION_CHECK', '실린더 라이너 치수에 대한 추가 확인 요청이 접수되어 검토 의견을 요청함.');
INSERT INTO complaint (complaint_id, part_id, delivery_id, complaint_date, defect_type, complaint_message) VALUES (3006, 3, 2023, '2026-09-24', 'PACKAGING_DAMAGE', '베어링 완충 포장이 부족해 포장 보강을 요청함.');
INSERT INTO complaint (complaint_id, part_id, delivery_id, complaint_date, defect_type, complaint_message) VALUES (3007, 1, 2024, '2026-10-20', 'MISSING_LABEL', '분할 납품된 실린더 라이너 포장 일부의 식별 라벨 확인을 요청함.');
